import{_ as o,l as c,o as e,c as i,v as t,p as d,x as r,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"PCB 与 task_struct","description":"","frontmatter":{"title":"PCB 与 task_struct","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pcb-task-struct.md","filePath":"cs/pcb-task-struct.md","lastUpdated":1789023840000}'),u={name:"cs/pcb-task-struct.md"};function B(P,a,_,h,C,m){const s=c("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="pcb-与-task-struct" tabindex="-1">PCB 与 task_struct <a class="header-anchor" href="#pcb-与-task-struct" aria-label="Permalink to &quot;PCB 与 task_struct&quot;">​</a></h1><div class="epigraph"><p>进程控制块是内核里那份可调度对象的档案：状态、寄存器副本、内存与文件的指针，而不是用户看见的可执行文件。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Love, Linux Kernel Development 整理</footer></div><p><a href="/cs/process-image">上一课</a>把正在跑的程序收成映像：页表根、寄存器、资源表。缺口是：映像在内核里要有一个<strong>可挂队列、可命名、可指向</strong>的对象——教材称 PCB，Linux 称 <code>task_struct</code>。本课只钉这份结构的职责，不写 <code>fork</code> 如何复制它。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>调度器不能在用户页里找「下一个进程」：用户页会被换出，也不能被内核随便信。<a href="/cs/percpu">per-CPU 数据</a>是核本地的，进程却会迁移。缺口是内核堆上的控制块：PID、状态（运行/就绪/阻塞）、指向 trapframe 与内核栈、指向内存描述符与文件表。没有它，<a href="/cs/context-switch">上下文切换</a>没有保存目标。</p><p><span class="marginnote">Linux 里几乎一切可调度实体都是 <code>task_struct</code>，用户进程与内核线程共用。本课先按「一条控制流一份 PCB」理解，线程课再拆共享。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>创建：分配 PCB，填初始寄存器与页表，链入就绪结构（队列形状是调度课）。查找：按 PID 哈希或树。销毁：从队列摘下，释放描述符——前提是没有人还 <code>wait</code> 着读退出码，那是僵尸课。内核只通过 PCB 碰用户状态，不把 PCB 本身映给用户写。</p>',8)),(e(),d(p,null,{default:r(()=>[n(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PCB%5B%22PCB%20%2F%20task_struct%22%5D%20--%3E%20REGS%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E4%B8%8E%E5%86%85%E6%A0%B8%E6%A0%88%22%5D%0A%20%20PCB%20--%3E%20MM%5B%22%E5%86%85%E5%AD%98%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%0A%20%20PCB%20--%3E%20FS%5B%22%E6%96%87%E4%BB%B6%E4%B8%8E%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20PCB%20--%3E%20ST%5B%22%E8%B0%83%E5%BA%A6%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>PID 是给用户与 <code>kill</code> 用的整数名；内核内部用指针。命名空间如何虚拟化 PID，是更后的隔离课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>PCB 把「映像」变成可操作的内核类型。切换：保存到当前 PCB，恢复下一 PCB。<a href="/cs/syscall-path">系统调用路径</a>上的 <code>current</code> 就是正在用 CPU 的那块。文件偏移存在 PCB 指向的文件表里，所以同一二进制跑两份互不相干——上一课已点过，本课落到字段。</p><p>状态位与等待队列指针让阻塞有着落：睡在哪把锁、哪个管道，PCB 上要能找到，唤醒才知道叫醒谁。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>task_struct</code> 的几百个字段当词典，不写 cgroup 指针的会计语义。线程组、进程组字段存在，语义在后续课填。也不把用户可见的 <code>/proc/pid</code> 当成 PCB 本身：那是导出。</p><p>后课默认：可调度对象就是 PCB。第一份新 PCB 如何从旧的来，下一课讲 <code>fork</code>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PCB 是内核里的进程档案；Linux 名为 <code>task_struct</code>。</li><li>调度、切换、系统调用都通过它找到当前映像。</li><li>复制出子进程是下一课 <code>fork</code>。</li><li>出处：Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>。</li></ul>',9))])}const f=o(u,[["render",B]]);export{k as __pageData,f as default};
